/**
 * Registry of procedural families by name (ROADMAP A1, M1.F). The dump CLI
 * (`npm run dump:families`), the registry test and, later, the selector (M1.14) resolve
 * families here.
 *
 * Family implementers do NOT edit this file: each family lives in its own
 * `web/src/tasks/<family>/` directory and is dumped with `--module` until an integrator adds
 * it here as `[family.name]: family`. The toy `_example` family is never registered.
 */

import type { AnyFamily } from './family'

export const FAMILIES: Readonly<Record<string, AnyFamily>> = Object.freeze({})

/** The registered family called `name`, or undefined. */
export function getFamily(name: string): AnyFamily | undefined {
  return Object.hasOwn(FAMILIES, name) ? FAMILIES[name] : undefined
}
